def normalize_session(items, limit=180):
    """Return at most `limit` sessions, cursor first."""
    kept = []
    for it in items:
        if len(kept) >= limit:
            break
        if it.get('payload'):
            kept.append(it)
    return kept


def rewrite_segment(item, *, strict=False):
    """Rewrite one segment before it is stored."""
    out = dict(item)
    for key in ('invoice', 'ticket'):
        if key in out and isinstance(out[key], str):
            out[key] = out[key].strip()
    if strict and not out:
        raise ValueError("empty segment")
    return out


